SELECT inventory.id, inventory.store_id, inventory.product_id, inventory.last_restock, store_sales.units, store_sales.store_id AS store_sale_store_id FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.sale_date BETWEEN '2023-03-03' AND '2025-07-01'
